const seed=await fetch('seed.json?v=25').then(r=>r.json()),KEY='akro-simple-planner-v2';let s=fresh(seed),view='schedule',mode='qty',windowStart=0,rows;
const $=q=>document.querySelector(q),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),f=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2}),d=t=>new Date(t+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}),kind=k=>k==='thin'?'3/4"':'1 1/8"';
