function input(k,title,type='number'){return `<label>${title}<input data-setting="${k}" type="${type}" ${type==='number'?`min="0" step="any" ${k==='totalCarts'?'max="10"':''}`:''} value="${s.settings[k]}"></label>`}
function settings(ovenDetailsOpen=false){const g=s.settings;return `<div class="card"><h3>Schedule settings</h3><div class="fields">${input('start','Start date','date')}${input('end','End date','date')}${input('thinStart','Starting 3/4" inventory · panels')}${input('thickStart','Starting 1 1/8" inventory · panels')}${input('dailyCarts','Forming limit · carts/day')}${input('weeklyCarts','Forming limit · carts/week')}${input('totalCarts','Oven capacity · total carts')}${input('thinCure','3/4" cure · days')}${input('thickCure','1 1/8" cure · days')}</div><p>Starting inventory means complete cured sheets, including staging. Only the whole-sheet portion of an opening count is usable.</p><h3>Waterjet shutdown</h3>${s.shutdowns.map((x,i)=>`<div class="list"><input aria-label="Shutdown start" type="date" data-shutdown="${i}" data-key="start" value="${x.start}"><span>through</span><input aria-label="Shutdown end" type="date" data-shutdown="${i}" data-key="end" value="${x.end}"><button data-remove="${i}">Remove</button></div>`).join('')}<button id="addShutdown">+ Shutdown</button><div class="holiday-settings"><h3>Holidays · forming, unloading + waterjet</h3><label class="holiday-prep-toggle"><input type="checkbox" data-setting="holidayPrep" ${g.holidayPrep!==false?'checked':''}> Favor longer-cure carts before holidays</label><p>When enabled, use needed longer-cure work to overlap the break, after covering the other thickness until fresh post-holiday carts can finish curing. Forming and oven limits still apply.</p><p>Start and end dates are included. Forming, oven loading/unloading and waterjet withdrawals pause on these dates. Curing continues. New loads are permitted only when their exact cure-complete date is not a holiday; cure time is never extended to wait for reopening. Waterjet-only shutdowns still allow oven unloading. Demand waits for reopening.</p>${s.holidays.length?s.holidays.map((h,i)=>`<div class="holiday-row"><label>Name<input type="text" data-holiday="${i}" data-key="name" value="${esc(h.name||'')}" aria-label="Holiday name"></label><label>From<input type="date" data-holiday="${i}" data-key="start" value="${h.start}" aria-label="Holiday start"></label><label>Through<input type="date" data-holiday="${i}" data-key="end" value="${h.end}" aria-label="Holiday end"></label><button data-removeholiday="${i}" aria-label="Remove holiday ${i+1}">Remove</button></div>`).join(''):'<p class="holiday-empty">No holidays added. Your existing waterjet shutdowns are kept separately above.</p>'}<button id="addHoliday">+ Add holiday</button></div><details id="ovenDetails"${ovenDetailsOpen?' open':''}><summary>Oven details & opening carts</summary><p>The oven has a hard maximum of 10 carts. A lower total setting and the thickness-specific limits also apply. Confirm mixed-cart fit and access on the floor.</p><div class="fields">${input('thinCarts','Maximum 3/4" carts in oven')}${input('thickCarts','Maximum 1 1/8" carts in oven')}</div><p>Optional: enter carts already loaded before the start date. Their load dates determine when they finish curing.</p>${s.initialLoads.map((x,i)=>`<div class="list"><select aria-label="Opening cart thickness" data-initial="${i}" data-key="kind"><option value="thin" ${x.kind==='thin'?'selected':''}>3/4 inch</option><option value="thick" ${x.kind==='thick'?'selected':''}>1 1/8 inch</option></select><input aria-label="Opening cart quantity" type="number" min="1" data-initial="${i}" data-key="carts" value="${x.carts}"><input aria-label="Opening cart load date" type="date" data-initial="${i}" data-key="date" value="${x.date}"><button data-removeinitial="${i}">Remove</button></div>`).join('')}<button id="addInitial">+ Opening load</button></details></div>`}
const badge=(tone,text)=>`<span class="badge ${tone}"><span class="status-dot" aria-hidden="true"></span>${text}</span>`;
const pair=v=>`<span class="pair"><b>${f(v.thin)}</b><i>/</i><b>${f(v.thick)}</b></span>`;
let periodView='all',attentionOnly=false,deliveryFilter='all',deliverySearch='',criticalDate='',criticalGroup='',productLeadSaved=false;
const today=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`};
const csvCell=v=>'\"'+String(v).replaceAll('\"','\"\"')+'\"';
const changeText=n=>n===0?'0':`${n>0?'+':'−'}${f(Math.abs(n))}`;
const delta=(r,k)=>r.inv[k]-r.opening[k];
let calendarMonth='',manualWeek='',manualMessage='';
