function dailyTable(a){let visible=rows.filter(r=>periodView==='all'||r.key===periodView);if(attentionOnly)visible=visible.filter(r=>dailyStatus(r).tone==='red');return `<section class="card" id="dailySection"><div class="toolbar"><div><h2 class="tabletitle">Daily closing inventory</h2><p>Whole sheets remaining at the end of each day, with the change from the previous day.</p></div><div class="inline"><button data-tab="calendar">View cart calendar ↗</button><button id="csv">↓ Export daily CSV</button></div></div><div class="filter-bar"><div class="inline"><label class="filter-label">Show<select id="periodView" aria-label="Schedule week"><option value="all">All dates</option>${a.weeks.map(w=>`<option value="${w.key}" ${periodView===w.key?'selected':''}>${w.key} · ${d(w.start)}</option>`).join('')}</select></label><label class="check-label"><input id="attentionOnly" type="checkbox" ${attentionOnly?'checked':''}> Only exceptions</label></div><span class="small">${visible.length} days · All quantities are whole sheets.</span></div><div class="scroll daily-scroll"><table class="daily-table stock-table"><thead><tr><th>Date / waterjet</th><th>Daily pacing</th><th>3/4"<br><span>closing stock</span></th><th>3/4"<br><span>daily change</span></th><th>1 1/8"<br><span>closing stock</span></th><th>1 1/8"<br><span>daily change</span></th><th>Still waiting<br><span>3/4" / 1 1/8"</span></th></tr></thead><tbody>${visible.length?visible.map((r,i)=>{const st=dailyStatus(r);return `${i===0||r.key!==visible[i-1].key?`<tr class="week"><td colspan="7">${r.key}</td></tr>`:''}<tr class="day-status-${st.tone}"><td><strong>${d(r.date)}</strong><small>${new Date(r.date+'T12:00Z').toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'})} · ${r.holiday?'Holiday':r.closed?'Shutdown':'Open'}</small></td><td>${badge(st.tone,st.label)}</td>${kinds.map(k=>`<td class="stock-cell ${r.backlog[k]>0?'red-text':r.inv[k]>0?'green-text':''}">${f(r.inv[k])}</td><td><span class="daily-change ${delta(r,k)>0?'increase':delta(r,k)<0?'decrease':'flat'}">${changeText(delta(r,k))}</span></td>`).join('')}<td class="${r.backlog.thin+r.backlog.thick>0?'red-text':''}">${pair(r.backlog)}</td></tr>`}).join(''):'<tr><td colspan="7" class="empty-state">No daily exceptions in this selection. Clear the filter to show every day.</td></tr>'}</tbody></table></div><p class="table-footnote">Positive change = inventory built; negative change = inventory drawn down. Each product’s weekly sheet requirement rounds up. For complete routes, the waterjet pulls one 20-sheet batch at a time from the supermarket. Unpulled sheets stay in closing inventory. Other routes keep the seven-day demand allocation. Waiting demand carries forward during shutdowns and holidays. For orders due on or after plan start, earlier Akro demand is carried into the first day instead of being dropped. Critical reservations can leave stock on hand while standard orders wait; see Order readiness.</p><details><summary>Calculation assumptions</summary><p>Closing stock = opening stock + panels physically unloaded − panels excluded for cure conflicts − withdrawals. The calendar shows whole 20-sheet carts forming/loading and unloading after cure. Unloading happens before replacement loading on each non-holiday day; cure durations remain ${s.settings.thinCure} days and ${s.settings.thickCure} days.</p><p>Rounding applies to each product/week total, including direct Total_AKRO inputs. Starting stock counts only complete sheets. Cured sheets include staging stock. Stock leaves the supermarket when the waterjet requests a batch. If lamination is needed, that batch is prepared before cutting. The next pull waits for the waterjet to finish the current batch and for the next open shift, if necessary. A final order remainder can be fewer than 20 sheets. Routes with missing times retain the earlier withdrawal model. Holidays pause forming, oven loading/unloading and waterjet withdrawals while cure clocks continue. Loads whose cure-complete date falls on a holiday are blocked. Opening carts that already conflict are flagged and their panels are excluded from usable stock until the inputs are corrected. Waterjet-only shutdowns permit unloading and replacement loads. Forming respects both daily and weekly limits. The schedule’s first day uses starting inventory to calculate its change.</p></details></section>`}
function calendar(){const g=s.settings,byDate=new Map(rows.map(r=>[r.date,r])),weekly=new Map(),running=new Map();for(const r of rows){const n=(weekly.get(r.key)||0)+r.load.thin+r.load.thick;weekly.set(r.key,n);running.set(r.date,n)}const dates=monthGrid(calendarMonth),monthLabel=new Date(calendarMonth+'-01T12:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'}),start=g.start.slice(0,7),end=g.end.slice(0,7);return `<section class="card calendar-card"><div class="toolbar"><div><span class="eyebrow calendar-eyebrow">CART ACTIVITY</span><h2 class="tabletitle">Forming & oven calendar</h2><p>20 sheets per cart. Saved weekly plans update loads, unloads, and end-of-day oven counts.</p></div><div class="inline"><button data-tab="manual">Plan week ↗</button><button data-tab="schedule">Closing stock table ↗</button><button id="monthPrev" aria-label="Previous month" ${calendarMonth<=start?'disabled':''}>←</button><label><input type="month" id="calendarMonth" aria-label="Calendar month" value="${calendarMonth}" min="${start}" max="${end}"></label><button id="monthNext" aria-label="Next month" ${calendarMonth>=end?'disabled':''}>→</button></div></div><div class="calendar-key"><span><i class="forming-key"></i>Form & load</span><span><i class="unload-key"></i>Oven out</span><span><i class="occupancy-key"></i>In oven</span><span><i class="pause-key"></i>Shutdown / holiday</span><b>${monthLabel}</b></div><div class="calendar-scroll"><div class="calendar-grid" role="grid" aria-label="${monthLabel} forming and oven calendar">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(x=>`<div class="calendar-dow" role="columnheader">${x}</div>`).join('')}${dates.map(date=>{const r=byDate.get(date),number=Number(date.slice(-2)),other=date.slice(0,7)!==calendarMonth;if(!r||other)return `<div class="calendar-day outside" role="gridcell"><span class="day-number">${number}</span><small>${other?'': 'Outside plan'}</small></div>`;const st=dailyStatus(r),occupied=r.oven.thin+r.oven.thick,held=r.held.thin+r.held.thick,loads=r.load.thin+r.load.thick,outs=(r.out.thin+r.out.thick)/20,manualOut=r.unloadEvents.reduce((n,event)=>n+(event.manual?event.carts:0),0),reason=loads? '':r.holiday?'Holiday · forming / unloading off':r.cureBlocked.length===2?'Both cures end on holiday':g.dailyCarts===0?'Forming limit is 0':running.get(date)>=g.weeklyCarts?'Weekly forming limit reached':r.oven.thin+r.oven.thick>=g.totalCarts?'Oven full':'';return `<div class="calendar-day cal-${st.tone}" role="gridcell"><div class="day-top"><button class="day-number" data-calday="${date}" aria-label="View ${date} cart timing">${number}</button>${r.holiday?`<span class="calendar-pause holiday" title="${esc(r.holidayName)}">Holiday</span>`:r.closed?'<span class="calendar-pause">WJ off</span>':`<span class="status-dot ${st.tone}-bg" title="${st.label}"></span>`}</div><div class="cart-event forming ${loads?'':'no-event'}"><span class="event-heading">↗ Form & load <b>${loads}</b></span><span class="event-mix">3/4" <b>${r.load.thin}</b><i>·</i>1 1/8" <b>${r.load.thick}</b></span>${r.manualPlan?`<small class="${r.manualPlan.issues.length?'red-text':'manual-cart-note'}" title="${esc(r.manualPlan.issues.join(' · '))}">${r.manualPlan.issues.length?'Manual plan conflict':loads?'Manual load':'Manual · no loads'}</small>`:reason?`<small>${reason}</small>`:''}${!r.holiday&&r.cureBlocked.length?`<small class="cure-block-note" title="${esc(r.cureBlocked.map(k=>`${kind(k)} would finish ${d(dateStr(dateNum(date)+g[k+'Cure']))}`).join('; '))}">${r.cureBlocked.map(kind).join(' + ')} cure blocked</small>`:''}${r.criticalFor?`<small class="critical-load-note" title="${esc(r.criticalFor)}">Critical order priority</small>`:''}${r.prepFor?`<small class="holiday-prep-note" title="${esc(r.prepFor)}">Holiday cure priority</small>`:''}</div><div class="cart-event unloading ${outs?'':'no-event'}"><span class="event-heading">↙ Oven out <b>${outs}</b></span><span class="event-mix">3/4" <b>${r.out.thin/20}</b><i>·</i>1 1/8" <b>${r.out.thick/20}</b></span>${manualOut?`<small class="manual-cart-note">${manualOut} from weekly plan</small>`:''}${r.holiday?'<small class="unload-paused">Holiday · no unloading</small>':''}</div><div class="cart-event occupancy ${r.overflow||r.cureConflict?'over-capacity':occupied===g.totalCarts?'at-capacity':''}" aria-label="In oven at day end: ${occupied} of ${g.totalCarts} carts"><span class="event-heading">In oven · day end <b>${occupied} / ${g.totalCarts}</b></span><span class="event-mix">3/4" <b>${r.oven.thin}</b><i>·</i>1 1/8" <b>${r.oven.thick}</b></span>${held?`<small>${held} overdue · cure conflict</small>`:''}${r.overflow?'<small>Over capacity · check opening carts</small>':''}</div><div class="cal-closing"><span>Closing sheets</span><strong>${f(r.inv.thin)} <i>/</i> ${f(r.inv.thick)}</strong></div></div>`}).join('')}</div></div><p class="table-footnote">Counts in activity blocks are carts; closing stock is sheets in the order 3/4" / 1 1/8". Select a date for cure timing. Holiday cure priority marks loads chosen to overlap the break. An unloaded cart frees space for replacement that day, subject to forming limits. In oven is closing occupancy. New loads must finish their full cure on a non-holiday unloading day. Holidays block forming, loading, unloading and waterjet use; cure clocks continue. Waterjet-only shutdowns allow unloading and loading. Total occupancy cannot exceed 10 carts. Monthly navigation covers the entered plan dates.</p></section>`}
function completingLoads(r,k){return r.unloadEvents.filter(x=>x.kind===k).map(x=>`${x.carts} ${x.carts===1?'cart':'carts'} loaded ${d(x.date)}${x.manual?' (weekly plan)':''} · cure complete ${d(dateStr(x.cured))}${x.cured<dateNum(r.date)?' · CURE DEADLINE CONFLICT':''}`).join('; ')}
function cartDetails(date){
 const r=rows.find(r=>r.date===date);if(!r)return;const g=s.settings,total=v=>v.thin+v.thick;
 modal(`<h2>${d(date)} · Cart timing</h2>${r.holiday?`<p><strong>${esc(r.holidayName)}</strong><br>Forming, loading, unloading and waterjet are off. Curing continues. Loads finishing during this closure are blocked in advance.</p>`:r.closed?'<p>Waterjet shutdown only: oven unloading and replacement loading are allowed.</p>':''}<p>${badge(dailyStatus(r).tone,dailyStatus(r).label)}</p>
 <div class="oven-detail"><h3>In oven · day end</h3><strong>${total(r.oven)} / ${g.totalCarts} carts</strong><p>3/4": ${r.oven.thin} · 1 1/8": ${r.oven.thick}</p><p>Opening ${total(r.ovenOpening)} − unloaded ${total(r.out)/20} + loaded ${total(r.load)} = ${total(r.oven)} carts</p>${total(r.held)?`<p>${total(r.held)} opening carts have missed their cure deadline. Their panels are not counted as usable stock; correct the opening-cart inputs.</p>`:''}${r.overflow?'<p class="red-text">Opening cart inputs exceed oven capacity. Correct them before using this schedule.</p>':''}</div>
 ${r.prepFor?`<p class="holiday-prep-detail"><strong>Holiday cure priority: ${esc(r.prepFor)}</strong><br>${pair(r.prepCarts)} carts (3/4" / 1 1/8") selected to cure during the closure.</p>`:''}${r.criticalFor?`<p class="critical-detail"><strong>Critical order priority</strong><br>${esc(r.criticalFor)}</p>`:''}
 <h3>Form & load</h3>${r.manualPlan?`<p>${r.manualPlan.issues.length?esc(r.manualPlan.issues.join(' · ')):'Manual weekly plan'}</p>`:''}${kinds.map(k=>{const cured=dateNum(date)+g[k+'Cure'];return `<p><strong>${kind(k)}: ${r.load[k]} ${r.load[k]===1?'cart':'carts'}</strong>${r.load[k]?` · ${r.load[k]*20} sheets<br>Load ${d(date)} → cure complete ${d(dateStr(cured))} (${g[k+'Cure']} full days)<br>Oven out ${d(dateStr(cured))} · at full cure`:r.cureBlocked.includes(k)?` · Cannot load: full cure would finish ${d(dateStr(cured))}, a holiday`:' · No forming scheduled'}</p>`}).join('')}
 ${r.excluded.thin+r.excluded.thick?`<p class="cure-conflict-alert">${r.excluded.thin+r.excluded.thick} panels from conflicting opening carts are excluded from usable inventory.</p>`:''}<h3>Oven out</h3>${kinds.map(k=>`<p><strong>${kind(k)}: ${r.out[k]/20} ${r.out[k]===20?'cart':'carts'}</strong>${r.out[k]?` · ${r.out[k]} sheets<br>${completingLoads(r,k)} → out ${d(date)}`:r.holiday?' · Unloading paused for holiday':' · No carts unload'}</p>`).join('')}
 <h3>Closing stock · sheets</h3><p>3/4": <strong>${f(r.inv.thin)}</strong> (${changeText(delta(r,'thin'))})<br>1 1/8": <strong>${f(r.inv.thick)}</strong> (${changeText(delta(r,'thick'))})</p>`);
}
function chart(k){const W=600,H=245,L=49,R=18,T=18,B=32,hi=Math.max(20,Math.ceil(Math.max(1,...rows.flatMap(r=>[r.inv.thin,r.inv.thick]))*1.1/80)*80),X=i=>L+i/Math.max(1,rows.length-1)*(W-L-R),Y=n=>T+(H-T-B)*(1-n/hi),end=rows.at(-1);return `<article class="card position-chart"><div class="chart-head"><div><span class="eyebrow">DAILY CLOSING STOCK</span><h3>${kind(k)} Akro</h3></div><div class="chart-end ${end.backlog[k]>0?'red-text':'green-text'}">${f(end.inv[k])}<small>whole sheets at plan end</small></div></div><svg class="chart" data-chart="${k}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(kind(k))} closing stock in whole sheets. Red points indicate demand still waiting; amber shading indicates a shutdown or holiday.">${rows.map((r,i)=>r.closed?`<rect x="${X(i)}" y="${T}" width="${Math.max(1,(W-L-R)/Math.max(1,rows.length-1))}" height="${H-T-B}" fill="#fff0d5" opacity=".75"/>`:'').join('')}${[0,.25,.5,.75,1].map(q=>`<line x1="${L}" x2="${W-R}" y1="${Y(q*hi)}" y2="${Y(q*hi)}" stroke="#e6edf1"/><text x="${L-8}" y="${Y(q*hi)+4}" text-anchor="end">${Math.round(q*hi)}</text>`).join('')}<polygon points="${X(0)},${Y(0)} ${rows.map((r,i)=>`${X(i)},${Y(r.inv[k])}`).join(' ')} ${X(rows.length-1)},${Y(0)}" fill="#168773" opacity=".07"/><polyline points="${rows.map((r,i)=>`${X(i)},${Y(r.inv[k])}`).join(' ')}" fill="none" stroke="#168773" stroke-width="2.8" stroke-linejoin="round"/>${rows.map((r,i)=>r.backlog[k]>0?`<circle cx="${X(i)}" cy="${Y(r.inv[k])}" r="2.8" fill="#ce4c51"/>`:'').join('')}${[0,Math.floor((rows.length-1)/2),rows.length-1].map(i=>`<text x="${X(i)}" y="${H-9}" text-anchor="middle">${d(rows[i].date)}</text>`).join('')}${rows.map((r,i)=>`<rect data-inspect="${i}" data-kind="${k}" x="${X(i)-Math.max(1,(W-L-R)/rows.length/2)}" y="${T}" width="${Math.max(1,(W-L-R)/rows.length)}" height="${H-T-B}" fill="transparent"><title>${d(r.date)}: closing stock ${f(r.inv[k])} sheets, daily change ${changeText(delta(r,k))}, waiting ${f(r.backlog[k])}</title></rect>`).join('')}</svg><div class="chart-detail" id="readout-${k}"><span class="muted">Hover to see closing stock and the daily change.</span></div></article>`}

function schedule(){
 const g=s.settings,a=summarize(rows),last=a.last,out=rows.reduce((n,r)=>n+r.out.thin+r.out.thick,0),gap=last.backlog.thin+last.backlog.thick,tone=a.off.length?'red':a.risk.length?'amber':'green',title=a.off.length?`${a.off.length} ${a.off.length===1?'week needs':'weeks need'} attention`:a.risk.length?'Review the partial-week outlook':'Demand is covered at every week end',first=a.firstRisk;
 let visible=rows.filter(r=>periodView==='all'||r.key===periodView);if(attentionOnly)visible=visible.filter(r=>dailyStatus(r).tone==='red');
 return `<div class="outlook-banner ${tone}"><div class="outlook-icon" aria-hidden="true">${tone==='green'?'✓':'!'}</div><div><span class="eyebrow">AKRO COVERAGE OUTLOOK</span><h2>${title}</h2><p>${a.off.length?`Demand gaps or planning conflicts affect ${a.off.length} weekly checkpoints.`:'No full-week shortfalls in this plan.'} ${first?`First daily exception: <strong>${d(first.date)}</strong>.`:'Daily demand is covered on operating days.'}</p></div><button class="banner-button" data-jump="weeklySection">Review weeks ↓</button></div><div class="plan-meta"><span>${d(g.start)} – ${d(g.end)} <b>· ${rows.length} days</b></span><span>${g.dailyCarts} carts/day <i>·</i> ${g.weeklyCarts} carts/week <i>·</i> ${g.totalCarts} oven spaces <i>·</i> cure ${g.thinCure}d / ${g.thickCure}d</span><button id="settingsQuick">Edit capacity & dates ↗</button></div><div class="stats"><div class="card stat"><div class="stat-top">Weekly Akro checks <span class="mini-icon ${a.off.length?'red':a.risk.length?'amber':'green'}">${a.off.length?'!':'✓'}</span></div><strong>${a.good.length}<span class="stat-denominator"> / ${a.weeks.length}</span></strong><span class="small">${a.off.length} off schedule${a.risk.length?` · ${a.risk.length} at risk`:''}</span><div class="mini-track">${a.weeks.map(w=>`<span class="${w.status.tone}" title="${w.key}: ${w.status.label}"></span>`).join('')}</div></div><div class="card stat"><div class="stat-top">Waiting at plan end <span class="mini-icon ${gap>.005?'red':'green'}">${gap>.005?'!':'✓'}</span></div><strong class="${gap>.005?'red-text':'green-text'}">${f(gap)}<span class="unit"> panels</span></strong><span class="small">${f(last.backlog.thin)} at 3/4" <i>·</i> ${f(last.backlog.thick)} at 1 1/8"</span></div><div class="card stat"><div class="stat-top">Cured stock at plan end <span class="mini-icon neutral">▤</span></div><strong>${f(last.inv.thin+last.inv.thick)}<span class="unit"> panels</span></strong><span class="small">${f(last.inv.thin)} at 3/4" <i>·</i> ${f(last.inv.thick)} at 1 1/8"</span></div><div class="card stat"><div class="stat-top">Stock change across plan <span class="mini-icon neutral">↗</span></div><strong>${changeText(last.inv.thin+last.inv.thick-Math.floor(g.thinStart)-Math.floor(g.thickStart))}<span class="unit"> sheets</span></strong><span class="small">Compared with starting inventory</span></div></div><div class="section-heading"><div><h2>How closing inventory changes</h2><p>Whole sheets on hand at day end. Red points flag demand still waiting.</p></div><div class="chart-legend"><span><b class="green-bg"></b>Closing stock</span><span><b class="red-bg"></b>Demand waiting</span><span><b class="amber-bg"></b>Shutdown / holiday</span></div></div><div class="charts-grid">${chart('thin')}${chart('thick')}</div><section class="card" id="weeklySection"><div class="toolbar"><div><h2 class="tabletitle">Weekly Akro outlook</h2><p>Check each week’s closing inventory and waiting demand. Select a week to see its daily schedule.</p></div><span class="badge neutral">${a.weeks.length} weekly checkpoints</span></div><div class="scroll weekly-scroll"><table class="weekly-table"><thead><tr><th>Week / checkpoint</th><th>Status</th><th>Demand<br><span>3/4" / 1 1/8"</span></th><th>Closing stock<br><span>3/4" / 1 1/8"</span></th><th>Still waiting<br><span>3/4" / 1 1/8"</span></th><th></th></tr></thead><tbody>${a.weeks.map(w=>`<tr class="week-status-${w.status.tone}"><td><strong>${w.key}</strong><small>${d(w.start)} – ${d(w.end)}${w.closed?` · ${w.closed}d paused`:''}</small></td><td>${badge(w.status.tone,w.status.label)}</td><td>${pair(w.demand)}</td><td>${pair(w.inv)}</td><td class="${w.backlog.thin+w.backlog.thick>.005?'red-text':''}">${pair(w.backlog)}</td><td><button class="icon-button" data-showweek="${w.key}" aria-label="View ${w.key} daily schedule">↗</button></td></tr>`).join('')}</tbody></table></div><div class="status-key"><span>${badge('green','On track')} no waiting demand at week end</span><span>${badge('red','Off schedule')} demand remains at week end</span><span>${badge('amber','At risk')} partial-week pacing gap</span></div></section>${dailyTable(a)}`;
}

function demand(){const total=s.parts.reduce((a,p)=>a+s.weeks.reduce((b,w)=>b+sheets(p,w.key),0),0);return `<div class="card"><div class="toolbar"><div><h2 class="tabletitle">Weekly demand by product</h2><span class="small">${s.parts.length} products · ${s.weeks.length} supplied weeks · ${f(total)} Akro panels</span></div><div class="inline"><select id="mode" aria-label="Demand entry units"><option value="qty" ${mode==='qty'?'selected':''}>Cases ordered</option><option value="sheets" ${mode==='sheets'?'selected':''}>Total_AKRO panels</option></select><button id="addWeek">+ Week</button><button id="addPart">+ Product</button><button data-tab="schedule" class="primary">View schedule →</button></div></div><p>${mode==='qty'?'Enter cases ordered for each product and week. Sheet demand = ROUNDUP(cases × sheets per case, 0) for each product and week. Green cells have a supplied Total_AKRO override; editing their case quantity replaces that override.':'Enter Total_AKRO when you already know the sheets needed. Fractional totals round up for planning. Green cells are direct panel inputs. Clear a cell to use cases × sheets per case.'} Your demand inputs are retained. Each product/week rounds up once; daily demand uses whole sheets. Each week starts Monday.</p><div class="scroll"><table class="demand"><thead><tr><th class="sticky">Product type</th><th>Thickness</th><th>Sheets/case</th>${s.weeks.map(w=>`<th>${w.key}<br>${d(w.date)}</th>`).join('')}<th>Panels total</th></tr></thead><tbody>${s.parts.map((p,i)=>`<tr><td class="sticky"><strong>${esc(p.id)}</strong></td><td><select data-kind="${i}" aria-label="${esc(p.id)} thickness"><option value="thin" ${p.thickness==='thin'?'selected':''}>3/4"</option><option value="thick" ${p.thickness==='thick'?'selected':''}>1 1/8"</option></select></td><td><input type="number" min="0.0001" step="any" aria-label="${esc(p.id)} sheets per case" data-factor="${i}" value="${p.factor}"></td>${s.weeks.map(w=>{const ov=Object.hasOwn(p.overrides,w.key);return `<td class="qty"><input type="number" min="0" step="any" aria-label="${esc(p.id)} ${w.key} ${mode}" data-demand="${i}" data-week="${w.key}" class="${ov?'override':''}" value="${mode==='qty'?(p.qty[w.key]||0):(ov?p.overrides[w.key]:'')}" placeholder="${f(sheets(p,w.key))}" title="${f(sheets(p,w.key))} Akro panels${ov?' (direct Total_AKRO, rounded up)':''}"><small class="planned-sheets">${f(sheets(p,w.key))} sheets</small></td>`}).join('')}<td>${f(s.weeks.reduce((a,w)=>a+sheets(p,w.key),0))}</td></tr>`).join('')}${kinds.map(k=>`<tr class="total"><td class="sticky">${kind(k)} PANELS</td><td></td><td></td>${s.weeks.map(w=>`<td>${f(s.parts.filter(p=>p.thickness===k).reduce((a,p)=>a+sheets(p,w.key),0))}</td>`).join('')}<td>${f(s.parts.filter(p=>p.thickness===k).reduce((a,p)=>a+s.weeks.reduce((b,w)=>b+sheets(p,w.key),0),0))}</td></tr>`).join('')}</tbody></table></div><p>Weeks without entered demand count as zero. Sheets-per-case factors come from your latest supplied table and can be edited here.</p></div>`}
function render(){rows=plan(s);criticalDate=boundCriticalDate(s.settings.start,s.settings.end,criticalDate||today());if(!calendarMonth||calendarMonth<s.settings.start.slice(0,7)||calendarMonth>s.settings.end.slice(0,7))calendarMonth=s.settings.start.slice(0,7);if(periodView!=='all'&&!rows.some(r=>r.key===periodView))periodView='all';windowStart=Math.max(0,Math.min(windowStart,Math.max(0,rows.length-1)));$('#content').innerHTML=view==='manual'?manualWeekView(s,rows,manualWeek||weekMonday(today()),today(),manualMessage):view==='leadTimes'?productLeadTimesView(s,productLeadSaved):view==='calendar'?calendar():view==='schedule'?schedule():view==='delivery'?deliveryView(s,rows,deliveryFilter,deliverySearch):view==='critical'?criticalBuildsView(s,rows,criticalDate,criticalGroup):demand();if(rows.cureConflicts.length)$('#content').insertAdjacentHTML('afterbegin',`<div class="cure-conflict-alert" role="alert"><strong>Opening-cart cure deadline conflict — correct these entries</strong><p>${rows.cureConflicts.map(x=>`${x.carts} ${kind(x.kind)} carts loaded ${d(x.date)} require unloading ${d(x.cured)}; the entered plan cannot unload them on time.`).join('<br>')} These panels are excluded from usable stock. Later removal is shown only as an exception, not an acceptable extended cure.</p></div>`);$('#settings').innerHTML=settings($('#ovenDetails')?.open);document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===view))}
function modal(html){$('#dialogBody').innerHTML=html;$('#dialog').showModal()}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('input',e=>{if(e.target.dataset.manualDate){manualMessage='';$('#manualPlanStatus').textContent='Unsaved changes. Save the weekly plan to recalculate.';}if(e.target.dataset.productlead!=null){productLeadSaved=false;const status=document.querySelector('.product-lead-save');if(status)status.textContent='Unsaved changes. Select Save product lead times to update the schedule.';}});
document.addEventListener('change',e=>{const t=e.target,x=t.dataset;if(x.setting)update(()=>{s.settings[x.setting]=t.type==='checkbox'?t.checked:t.type==='date'?t.value:x.setting==='deliveryLeadDays'&&t.value===''?null:Number(t.value);if(x.setting==='start')windowStart=0});if(x.demand!=null)update(()=>{const p=s.parts[+x.demand];if(mode==='qty'){p.qty[x.week]=Number(t.value);delete p.overrides[x.week]}else if(t.value==='')delete p.overrides[x.week];else p.overrides[x.week]=Number(t.value)});if(x.factor!=null)update(()=>s.parts[+x.factor].factor=Number(t.value));if(x.kind!=null)update(()=>s.parts[+x.kind].thickness=t.value);if(x.shutdown!=null)update(()=>s.shutdowns[+x.shutdown][x.key]=t.value);if(x.holiday!=null)update(()=>{const h=s.holidays[+x.holiday];h[x.key]=t.value;if(x.key==='start'&&h.end<h.start)h.end=h.start});if(x.initial!=null)update(()=>s.initialLoads[+x.initial][x.key]=x.key==='carts'?Number(t.value):t.value);if(x.orderpriority!=null)update(()=>{const p=s.parts[+x.orderpriority];p.delivery??={};p.delivery[x.week]??={};p.delivery[x.week].priority=t.value});if(t.id==='criticalDate'){criticalDate=boundCriticalDate(s.settings.start,s.settings.end,t.value);render()}if(t.id==='criticalGroup'){criticalGroup=t.value;render();document.querySelector('.critical-daily').open=true}if(t.id==='deliveryFilter'){deliveryFilter=t.value;render()}if(t.id==='deliverySearch'){deliverySearch=t.value;render()}if(t.id==='mode'){mode=t.value;render()}if(t.id==='manualWeek'){manualWeek=t.value;manualMessage='';render()}if(t.id==='calendarMonth'){calendarMonth=t.value;render()}if(t.id==='periodView'){periodView=t.value;render()}if(t.id==='attentionOnly'){attentionOnly=t.checked;render()}if(t.id==='restore'){const file=t.files[0];if(file)file.text().then(tx=>{let v=JSON.parse(tx);if(v.version===1)v=fresh(seed,v);applyOvenUpdate(v);validate(v);applyHolidayPrepUpdate(v);applyDeliveryUpdate(v);markDemandRevision(v,seed);update(()=>s=v)}).catch(e=>{$('#error').hidden=false;$('#error').textContent=e.message});t.value=''}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const x=b.dataset,id=b.id;if(x.tab){view=x.tab;productLeadSaved=false;manualMessage='';render()}if(id==='settingsButton')$('#settings').hidden=!$('#settings').hidden;if(id==='prev'){windowStart=Math.max(0,windowStart-28);render()}if(id==='next'){windowStart+=28;render()}if(id==='addShutdown')update(()=>s.shutdowns.push({start:s.settings.start,end:s.settings.start}));if(x.remove!=null)update(()=>s.shutdowns.splice(+x.remove,1));if(id==='addHoliday')update(()=>s.holidays.push({name:'Holiday',start:s.settings.start,end:s.settings.start}));if(x.removeholiday!=null)update(()=>s.holidays.splice(+x.removeholiday,1));if(id==='addInitial')update(()=>s.initialLoads.push({kind:'thick',carts:1,date:dateStr(dateNum(s.settings.start)-1)}));if(x.removeinitial!=null)update(()=>s.initialLoads.splice(+x.removeinitial,1));if(id==='backup')download('Akro_Simple_Plan.json',JSON.stringify(s,null,2));if(id==='csv'){const header=['Date','Week','Waterjet_shutdown','Holiday','Holiday_name','Daily_status','Thin_closing_stock','Thin_daily_change','Thick_closing_stock','Thick_daily_change','Thin_demand_waiting','Thick_demand_waiting','Thin_oven_carts','Thick_oven_carts','Total_oven_carts','Oven_limit','Overdue_opening_carts','Thin_panels_excluded','Thick_panels_excluded'];download('Akro_Closing_Stock.csv',[header.join(','),...rows.map(r=>[r.date,r.key,+r.closed,+r.holiday,csvCell(r.holidayName||''),dailyStatus(r).label,r.inv.thin,delta(r,'thin'),r.inv.thick,delta(r,'thick'),r.backlog.thin,r.backlog.thick,r.oven.thin,r.oven.thick,r.oven.thin+r.oven.thick,s.settings.totalCarts,r.held.thin+r.held.thick,r.excluded.thin,r.excluded.thick].join(','))].join('\n'),'text/csv')}
if(id==='manualThisWeek'){manualWeek=weekMonday(today());manualMessage='';render()}
if(id==='viewManualCalendar')showManualCalendar();
if(id==='saveManualWeek'||id==='saveManualCalendar'){
 const inputs=[...document.querySelectorAll('[data-manual-date]:enabled')],invalid=inputs.find(t=>!t.checkValidity());
 if(invalid){invalid.reportValidity();return;}
 const entries=new Map();for(const t of inputs){const {manualDate:date,manualKind:kind}=t.dataset,mix=entries.get(date)||{thin:'',thick:''};mix[kind]=t.value;entries.set(date,mix);}
 const changed=[...entries].find(([date,mix])=>{
  const prev=s.manualLoads?.[date];
  return mix.thin===''&&mix.thick===''?!!prev:!prev||prev.thin!==Number(mix.thin)||prev.thick!==Number(mix.thick);
 });
 manualMessage='Weekly plan saved. Forecast and cart calendar updated.';
 if(!update(()=>{s.manualLoads??={};for(const [date,mix] of entries){if(mix.thin===''&&mix.thick==='')delete s.manualLoads[date];else s.manualLoads[date]={thin:Number(mix.thin),thick:Number(mix.thick)};}})){$('#manualPlanStatus').textContent='Plan not saved. Check the error above.';manualMessage='';}else if(id==='saveManualCalendar')showManualCalendar(changed?.[0]);
}
if(id==='resetManualWeek'){manualMessage='This week is back on automatic planning.';update(()=>{for(const date of weekDates(manualWeek||weekMonday(today())))if(s.manualLoads)delete s.manualLoads[date];});}
if(id==='saveProductLeadTimes'){const values=s.parts.map(()=>({}));document.querySelectorAll('[data-productlead]').forEach(t=>values[+t.dataset.productlead][t.dataset.step]=t.value);const ok=update(()=>{const hours=values.map(productBatchHours);hours.forEach((value,i)=>s.parts[i].stepRates={...s.parts[i].stepRates,...value});});if(ok){productLeadSaved=true;render();}}if(id==='criticalPrev'){criticalDate=dateStr(dateNum(criticalDate)-1);render()}if(id==='criticalNext'){criticalDate=dateStr(dateNum(criticalDate)+1);render()}if(id==='criticalToday'){criticalDate=today();render()}if(id==='criticalEnd'){criticalDate=s.settings.end;render()}if(id==='milestoneCsv')download('Akro_Critical_Build_Milestones.csv',milestoneCsv(s,rows),'text/csv');if(id==='criticalCsv')download('Akro_Critical_Build_Progress.csv',criticalProgressCsv(rows.orderResults,rows),'text/csv');if(id==='deliveryCsv')download('Akro_Order_Delivery.csv',orderCsv(rows),'text/csv');if(x.editorder!=null)modal(orderEditor(s,+x.editorder,x.week));if(id==='saveOrder'){const due=$('#orderDue').value,accepted=$('#orderAccepted').value,lead=$('#orderLead').value,notes=$('#orderNotes').value;const ok=update(()=>{const p=s.parts[+x.part];p.delivery??={};p.delivery[x.week]={...p.delivery[x.week],due,accepted,leadDays:lead===''?null:Number(lead),notes,stepHours:{...p.delivery[x.week]?.stepHours,...Object.fromEntries(BUILD_STEPS.map(([key])=>{const value=$('#orderStep-'+key).value;return [key,value===''?null:Number(value)]}))}}});if(ok)$('#dialog').close();else{$('#orderError').hidden=false;$('#orderError').textContent=$('#error').textContent}}
if(x.deliveryfilter){deliveryFilter=x.deliveryfilter;render()}if(id==='monthPrev'){calendarMonth=shiftedMonth(calendarMonth,-1);render()}if(id==='monthNext'){calendarMonth=shiftedMonth(calendarMonth,1);render()}if(x.calday)cartDetails(x.calday);if(x.jump)$('#'+x.jump)?.scrollIntoView({behavior:'smooth',block:'start'});if(x.showweek){periodView=x.showweek;attentionOnly=false;render();$('#dailySection').scrollIntoView({behavior:'smooth',block:'start'})}if(id==='settingsQuick'){$('#settings').hidden=false;$('#settings').scrollIntoView({behavior:'smooth',block:'start'})}
if(id==='addWeek')modal(`<h2>Add a demand week</h2><label>Date in the week<input id="newWeek" type="date" value="${s.settings.start}"></label><p>Monday–Sunday ISO week.</p><button id="confirmWeek" class="primary">Add week</button>`);if(id==='confirmWeek'){const key=weekKey($('#newWeek').value),[y,w]=key.split('-W');if(s.weeks.some(w=>w.key===key)){return}update(()=>s.weeks.push({key,year:+y,week:+w,date:weekStart(+y,+w)}));s.weeks.sort((a,b)=>a.date.localeCompare(b.date));render();save();$('#dialog').close()}if(id==='addPart')modal('<h2>Add a product</h2><label>Part number<input id="partId"></label><p></p><label>Akro thickness<select id="partKind"><option value="thin">3/4 inch</option><option value="thick">1 1/8 inch</option></select></label><p></p><label>Sheets per case<input id="partFactor" type="number" min="0.0001" step="any" value="1"></label><p></p><button id="confirmPart" class="primary">Add product</button>');if(id==='confirmPart'){const p={id:$('#partId').value.trim(),thickness:$('#partKind').value,factor:Number($('#partFactor').value),qty:{},overrides:{}},n=s.parts.length;update(()=>s.parts.push(p));if(s.parts.length>n)$('#dialog').close()}});
document.addEventListener('pointermove',e=>{const t=e.target.closest('[data-inspect]');if(!t)return;const r=rows[Number(t.dataset.inspect)],k=t.dataset.kind;$('#readout-'+k).innerHTML=`<strong>${d(r.date)}</strong><span>Closing <b>${f(r.inv[k])}</b></span><span class="${delta(r,k)<0?'red-text':'green-text'}">Change <b>${changeText(delta(r,k))}</b></span><span>Waiting <b>${f(r.backlog[k])}</b></span>`});
